use js_reformat::{ReformatOptions, reformat};

const HEADER: &str = "// Generated by ReScript, PLEASE EDIT WITH CARE\n";
const EMPTY: &str = "/* This output is empty. Its source's type definitions, externals and/or unused code got optimized away. */";

fn fixed(source: &str, options: ReformatOptions) -> String {
    let output = reformat(source, options).unwrap();
    assert_eq!(reformat(&output, options).unwrap(), output);
    output
}

#[test]
fn envelope_is_exact_and_body_is_normalized() {
    let preamble = format!("first directive;\r\nsecond directive;\n{HEADER}");
    let trailer = "\n\n/* value Not a pure module */\r\n//# sourceMappingURL=example.map\n";
    let source = format!("{preamble}\nlet x=(((1)));{trailer}");
    assert!(reformat(&source, ReformatOptions::default()).is_err());
    for strip_comments in [false, true] {
        let options = ReformatOptions {
            split_file: true,
            strip_comments,
            ..Default::default()
        };
        assert_eq!(
            fixed(&source, options),
            format!("{preamble}let x = 1;{trailer}")
        );
    }
}

#[test]
fn empty_output_headerless_and_commonjs() {
    let options = ReformatOptions {
        split_file: true,
        ..Default::default()
    };
    for source in [
        format!("{HEADER}{EMPTY}\n"),
        format!("{EMPTY}\n"),
        String::new(),
    ] {
        assert_eq!(fixed(&source, options), source);
    }
    assert_eq!(
        fixed("'use strict';\nlet x=1;\n/* No side effect */", options),
        "\"use strict\";\nlet x = 1;\n/* No side effect */"
    );
    assert!(reformat("arbitrary directive;", options).is_err());
}

#[test]
fn trailer_lookalikes_are_not_file_comments() {
    let options = ReformatOptions {
        split_file: true,
        ..Default::default()
    };
    let output = fixed("let x = `text\n/* No side effect */\n`;", options);
    assert!(output.contains("`text\n/* No side effect */\n`"));
    let output = fixed("/* No side effect */\nlet x=1;", options);
    assert!(output.ends_with("let x = 1;\n"));
}

#[test]
fn decoration_removal_is_opt_in_and_token_aware() {
    let source = "let x = {a: /* [] */0, b: /* 'a' */97, c: /* tag */(0).x, d: /* keep */foo, e: '/* [] */0', f: /* keep */-1, g: /* keep */1n};";
    let ordinary = fixed(source, ReformatOptions::default());
    assert!(ordinary.contains("/* [] */"));
    let output = fixed(
        source,
        ReformatOptions {
            drop_decoration_comments: true,
            ..Default::default()
        },
    );
    assert!(!output.contains("/* 'a' */"));
    assert!(!output.contains("/* tag */"));
    assert!(output.contains("a: 0"));
    assert!(output.contains("/* keep */ foo"));
    assert!(output.contains("\"/* [] */0\""));
    assert!(output.contains("/* keep */ -1"));
    assert!(output.contains("/* keep */ 1n"));
    let stripped = fixed(
        source,
        ReformatOptions {
            strip_comments: true,
            ..Default::default()
        },
    );
    assert!(!stripped.contains("/* keep */"));
}

#[test]
fn jsx_sequences_in_children_attributes_and_nested_elements_reparse() {
    let source =
        "let x = <><A value={(a(), b)}>{(c, <B p={(d, e)} />)}</A>{'comma, text'}{fn(a, b)}</>;";
    let output = fixed(source, ReformatOptions::default());
    assert!(output.contains("value={(a(), b)}"), "{output}");
    assert!(output.contains("p={(d, e)}"), "{output}");
    assert!(output.contains("{(c, <B"), "{output}");
    assert!(output.contains("{fn(a, b)}"), "{output}");
}

#[test]
fn committed_regressions() {
    let options = ReformatOptions {
        split_file: true,
        drop_decoration_comments: true,
        ..Default::default()
    };
    fixed(
        include_str!("../../../tests/tests/src/directives.mjs"),
        options,
    );
    fixed(
        include_str!("../../../tests/tests/src/jsx_preserve_cases.mjs"),
        options,
    );
    fixed(
        include_str!("../../../tests/tests/src/gpr_4632.mjs"),
        options,
    );
}

#[test]
fn indentation_is_two_spaces_and_a_fixed_point() {
    let options = js_reformat::ReformatOptions::default();
    let output = js_reformat::reformat("function f() { return 1; }", options).unwrap();
    assert_eq!(output, "function f() {\n  return 1;\n}\n");
    assert_eq!(js_reformat::reformat(&output, options).unwrap(), output);
}
